INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT128-S3-Q7$batch11$, 128, 3, 7, $batch11$Weaken$batch11$, $batch11$In an attempt to create brand loyalties, television advertisers currently target young adults, ages 18 to 25, because on average they have higher discretionary income than do consumers of other age groups. But since the average discretionary income of those over 65 will soon be greater than that of young adults, in the future television advertisers would do better to target consumers over 65 instead.$batch11$, $batch11$Which one of the following, if true, would most weaken the argument above?$batch11$, $batch11$B$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=128 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT128-S3-Q7$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Consumers over the age of 65 tend to watch different television shows than do young adults.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$The older a consumer is, the more likely he or she is to have already established brand loyalties.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$The average discretionary income of young adults is projected to rise in the near future.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$The greater a consumer's discretionary income, the more likely advertising is to encourage that consumer to buy.$batch11$, $batch11$Strengthener$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$The number of consumers over the age of 65 is increasing more rapidly than is the number of young adults.$batch11$, $batch11$Strengthener$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Advertisers aiming to build brand loyalty should target consumers over 65 instead of young adults.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Advertisers target young adults because they have the most discretionary income. Soon people over 65 will have more.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The goal is to create brand loyalty. Income matters only if the ads can win new loyalty. If older consumers have already settled on their brands, more income won't help advertisers create loyalty.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Show that older consumers are harder to win brand loyalty from.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Watching different shows means advertisers would choose different shows, not a different audience.$batch11$), ($batch11$B$batch11$, $batch11$Older consumers are more likely to have settled brand loyalties. Targeting them won't create new ones.$batch11$), ($batch11$C$batch11$, $batch11$Young adults' income rising doesn't tell us whether it will stay above that of those over 65.$batch11$), ($batch11$D$batch11$, $batch11$More income makes ads more effective, supporting a switch to the richer older group.$batch11$), ($batch11$E$batch11$, $batch11$More older consumers is another reason to target them.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT128-S3-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
